const SPEC_ACRONYMS: Record<string, string> = {
    co2: "CO\u2082", co: "CO", ph: "pH", uv: "UV", id: "ID", od: "OD",
    psi: "PSI", hz: "Hz", kw: "kW", kva: "kVA", vac: "VAC", vdc: "VDC",
    dc: "DC", ac: "AC", gc: "GC", ms: "MS", lc: "LC", iso: "ISO",
    ul: "UL", ce: "CE", rh: "RH", n2: "N\u2082", o2: "O\u2082", h2: "H\u2082",
};

function formatSpecWord(word: string): string {
    const lower = word.toLowerCase();
    if (SPEC_ACRONYMS[lower]) return SPEC_ACRONYMS[lower];
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
}

export function formatSpecLabel(label: string): string {
    if (!label) return label;
    // Already human-readable (has a space, or isn't plain snake_case) — leave as-is.
    if (label.includes(" ") || !/^[a-z0-9_]+$/i.test(label)) return label;
    let tokens = label.split("_");
    let prefix = "";
    const last = tokens[tokens.length - 1]?.toLowerCase();
    if (last === "min") { prefix = "Minimum "; tokens = tokens.slice(0, -1); }
    else if (last === "max") { prefix = "Maximum "; tokens = tokens.slice(0, -1); }
    const rest = tokens.map(formatSpecWord).join(" ");
    return (prefix + rest).trim();
}

